{"content":"import { useCallback } from 'react';
import { getApiBase } from '@/lib/api-base';
import { useAtom, useStore } from 'jotai';
import { addNodeAtom, viewportAtom } from '@/stores/workflow-store-jotai';
import type { NodeData } from '@/types/workflow-v1';
import type { Node } from '@xyflow/react';

interface UploadResult {
  localUrl: string;
  assetId: string;
}

interface AssetMeta {
  width: number;
  height: number;
  duration: number;
}

interface HandleFileResult {
  nodeId: string;
  assetId: string;
}

export function useAssetUpload() {
  const store = useStore();
  const [, addNode] = useAtom(addNodeAtom);

  // 上传文件到后端
  const uploadToBackend = useCallback(async (file: File): Promise<UploadResult | null> => {
    try {
      const formData = new FormData();
      formData.append('file', file);
      const resp = await fetch(`${getApiBase()}/api/upload`, {
        method: 'POST',
        body: formData,
      });
      if (!resp.ok) return null;
      const data = await resp.json();
      return {
        localUrl: `${getApiBase()}${data.path}`,
        assetId: data.asset_id,
      };
    } catch {
      return null;
    }
  }, []);

  // 提取文件元数据
  const extractMetadata = useCallback(async (file: File, assetType: 'IMAGE' | 'VIDEO'): Promise<AssetMeta> => {
    const fileUrl = URL.createObjectURL(file);
    let meta: AssetMeta = { width: 0, height: 0, duration: 0 };

    try {
      if (assetType === 'IMAGE') {
        const img = new window.Image();
        await new Promise<void>((resolve) => {
          img.onload = () => {
            meta = { width: img.naturalWidth, height: img.naturalHeight, duration: 0 };
            resolve();
          };
          img.onerror = () => resolve();
          img.src = fileUrl;
        });
      } else {
        const video = document.createElement('video');
        await new Promise<void>((resolve) => {
          video.onloadedmetadata = () => {
            meta = { width: video.videoWidth, height: video.videoHeight, duration: video.duration };
            resolve();
          };
          video.onerror = () => resolve();
          video.src = fileUrl;
        });
      }
    } finally {
      URL.revokeObjectURL(fileUrl);
    }

    return meta;
  }, []);

  // 获取素材编号
  const getNextAssetNumber = useCallback((type: 'IMAGE' | 'VIDEO'): number => {
    const key = `antoken_asset_counter_${type}`;
    const current = parseInt(localStorage.getItem(key) || '0', 10);
    const next = current + 1;
    localStorage.setItem(key, next.toString());
    return next;
  }, []);

  // 创建素材节点
  const createAssetNode = useCallback((
    assetType: 'IMAGE' | 'VIDEO',
    fileUrl: string,
    fileName: string,
    meta: AssetMeta,
    assetId?: string
  ): string => {
    const viewport = store.get(viewportAtom);
    const assetNumber = getNextAssetNumber(assetType);
    const assetName = assetType === 'IMAGE' ? `图素材${assetNumber}` : `视频素材${assetNumber}`;
    const centerX = (-viewport.x + window.innerWidth / 2) / viewport.zoom;
    const centerY = (-viewport.y + window.innerHeight / 2) / viewport.zoom;

    const nodeId = `${assetType}_${Date.now()}`;
    const newNode: Node<NodeData> = {
      id: nodeId,
      type: assetType,
      position: { x: centerX - 140, y: centerY - 100 },
      data: {
        label: assetType === 'IMAGE' ? '图片素材' : '视频素材',
        category: 'INPUT',
        nodeType: assetType,
        assetType,
        config: {
          assetUrl: fileUrl,
          assetName,
          originalWidth: meta.width,
          originalHeight: meta.height,
          originalDuration: meta.duration,
          isLocalAsset: true,
        },
        assetName,
        assetUrl: fileUrl,
        assetId,
      } as NodeData,
    };

    addNode(newNode);
    return nodeId;
  }, [addNode, store, getNextAssetNumber]);

  // 完整的文件处理流程
  const handleFile = useCallback(async (file: File, assetType: 'IMAGE' | 'VIDEO'): Promise<HandleFileResult | null> => {
    // 1. 提取元数据
    const meta = await extractMetadata(file, assetType);

    // 2. 上传到后端
    const uploadResult = await uploadToBackend(file);
    if (!uploadResult) return null;

    // 3. 创建节点
    const nodeId = createAssetNode(assetType, uploadResult.localUrl, file.name, meta, uploadResult.assetId);

    return { nodeId, assetId: uploadResult.assetId };
  }, [extractMetadata, uploadToBackend, createAssetNode]);

  return {
    handleFile,
    uploadToBackend,
    extractMetadata,
    createAssetNode,
    getNextAssetNumber,
  };
}
