{"content":"-- 创建积分扣减的原子操作函数
-- 这个函数在数据库层面保证原子性，避免并发问题

CREATE OR REPLACE FUNCTION deduct_credits(
  p_user_id UUID,
  p_month DATE,
  p_amount INTEGER
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_current_used INTEGER;
  v_total INTEGER := 1000; -- 默认值，应从用户计划获取
  v_new_used INTEGER;
  v_remaining INTEGER;
  v_success BOOLEAN;
  v_message TEXT;
BEGIN
  -- 使用行锁防止并发问题
  SELECT COALESCE(credits_used, 0)
  INTO v_current_used
  FROM usage_stats
  WHERE user_id = p_user_id AND month = p_month
  FOR UPDATE;

  -- 如果没有记录，创建一条
  IF v_current_used IS NULL THEN
    INSERT INTO usage_stats (user_id, month, credits_used)
    VALUES (p_user_id, p_month, 0);
    v_current_used := 0;
  END IF;

  -- 计算新的使用量
  v_new_used := v_current_used + p_amount;
  v_remaining := GREATEST(0, v_total - v_new_used);

  -- 检查是否超出限制
  IF v_new_used > v_total THEN
    v_success := FALSE;
    v_message := '积分不足';
  ELSE
    -- 更新使用量
    UPDATE usage_stats
    SET credits_used = v_new_used
    WHERE user_id = p_user_id AND month = p_month;

    v_success := TRUE;
    v_message := '扣减成功';
  END IF;

  -- 返回结果
  RETURN json_build_object(
    'success', v_success,
    'remaining', v_remaining,
    'message', v_message
  );
END;
$$;
