## 模块1 商业级重构：完整交付

---

## 目标
- **性能**：任何节点变化只重渲染依赖它的组件，支持数百节点流畅运行。  
- **类型安全**：更新节点数据字段编译时报错，杜绝拼写错误。  
- **撤销/重做**：智能快照策略，不保存拖拽中间状态，历史有意义。  
- **防错设计**：通过类型约束和原子封装，使新功能开发难以引入低级错误。  

---

## 1. 类型定义增强

### `types/workflow-v1.ts` (补充必要的类型)
```typescript
import type { Node, Edge } from '@xyflow/react';

// 节点数据核心字段
export interface NodeData {
  label: string;
  category: NodeCategory;
  nodeType: NodeFlowType;
  assetType?: AssetType;
  assetName?: string;
  assetUrl?: string;
  assetId?: string;
  config?: Record<string, unknown>;
  // 动态字段
  status?: 'idle' | 'running' | 'success' | 'error';
  progress?: number;
  description?: string;
  [key: string]: unknown;
}

export type NodeCategory = 'INPUT' | 'GENERATION' | 'COMPOSITE';
export type NodeFlowType = 'TEXT' | 'IMAGE' | 'VIDEO' | 'COMPOSITE';
export type AssetType = 'IMAGE' | 'VIDEO' | 'TEXT';
```

**说明**：`updateNodeData` 将使用 `Partial<NodeData>`，所有可更新字段均有类型检查。

---

## 2. 状态管理重构

### `stores/workflow-store-jotai.ts`

```typescript
import { atom } from 'jotai';
import { atomFamily } from 'jotai/utils';
import type { Node, Edge, OnNodesChange, OnEdgesChange, Connection } from '@xyflow/react';
import { applyNodeChanges, applyEdgeChanges, addEdge } from '@xyflow/react';
import type { NodeData } from '@/types/workflow-v1';

// ============================================================
// 基础原子
// ============================================================
export const nodesAtom = atom<Node[]>([]);
export const edgesAtom = atom<Edge[]>([]);
export const selectedNodeIdAtom = atom<string | null>(null);
export const showControlPanelAtom = atom<boolean>(false);
export const miniMapVisibleAtom = atom<boolean>(true);
export const workflowNameAtom = atom<string>('未命名项目');
export const viewportAtom = atom<{ x: number; y: number; zoom: number }>({ x: 0, y: 0, zoom: 0.7 });

// ============================================================
// 撤销/重做快照
// ============================================================
interface Snapshot {
  nodes: Node[];
  edges: Edge[];
}

export const undoStackAtom = atom<Snapshot[]>([]);
export const redoStackAtom = atom<Snapshot[]>([]);

// ============================================================
// 性能优化：节点/边按 ID 精确订阅
// ============================================================

/**
 * 获取单个节点，组件只在自己关注的节点变化时重渲染。
 * 用法：const node = useAtomValue(nodeAtomFamily('node-1'));
 */
export const nodeAtomFamily = atomFamily((nodeId: string) =>
  atom((get) => get(nodesAtom).find((n) => n.id === nodeId) ?? null)
);

/**
 * 获取单条边
 */
export const edgeAtomFamily = atomFamily((edgeId: string) =>
  atom((get) => get(edgesAtom).find((e) => e.id === edgeId) ?? null)
);

export const zoomLevelAtom = atom((get) => Math.round(get(viewportAtom).zoom * 100));
export const snapEnabledAtom = atom<boolean>(true);

// ============================================================
// 操作原子（强类型、防错设计）
// ============================================================

export const onNodesChangeAtom = atom(
  null,
  (get, set, changes: Parameters<OnNodesChange>[0]) => {
    set(nodesAtom, applyNodeChanges(changes, get(nodesAtom)));
  }
);

export const onEdgesChangeAtom = atom(
  null,
  (get, set, changes: Parameters<OnEdgesChange>[0]) => {
    set(edgesAtom, applyEdgeChanges(changes, get(edgesAtom)));
  }
);

export const onConnectAtom = atom(
  null,
  (get, set, connection: Connection) => {
    set(edgesAtom, addEdge(connection, get(edgesAtom)));
  }
);

export const addNodeAtom = atom(
  null,
  (get, set, node: Node) => {
    set(nodesAtom, [...get(nodesAtom), node]);
  }
);

export const removeNodeAtom = atom(
  null,
  (get, set, nodeId: string) => {
    set(nodesAtom, get(nodesAtom).filter((n) => n.id !== nodeId));
    set(edgesAtom, get(edgesAtom).filter((e) => e.source !== nodeId && e.target !== nodeId));
    if (get(selectedNodeIdAtom) === nodeId) {
      set(selectedNodeIdAtom, null);
    }
  }
);

export const removeEdgeAtom = atom(
  null,
  (get, set, edgeId: string) => {
    set(edgesAtom, get(edgesAtom).filter((e) => e.id !== edgeId));
  }
);

/**
 * 类型安全更新节点数据：只能更新 NodeData 中定义的字段。
 * 尝试更新未声明字段会编译报错。
 */
export const updateNodeDataAtom = atom(
  null,
  (get, set, nodeId: string, data: Partial<NodeData>) => {
    set(nodesAtom, get(nodesAtom).map((n) =>
      n.id === nodeId ? { ...n, data: { ...n.data, ...data } } : n
    ));
  }
);

export const selectNodeAtom = atom(
  null,
  (_get, set, nodeId: string | null) => {
    set(selectedNodeIdAtom, nodeId);
    set(showControlPanelAtom, true);
  }
);

export const selectNodeQuietlyAtom = atom(
  null,
  (_get, set, nodeId: string | null) => {
    set(selectedNodeIdAtom, nodeId);
  }
);

export const updateViewportAtom = atom(
  null,
  (_get, set, viewport: { x: number; y: number; zoom: number }) => {
    set(viewportAtom, viewport);
  }
);

// ============================================================
// 撤销/重做（精确快照策略）
// ============================================================

/**
 * 重大操作后保存快照（如添加、删除节点、应用配置）。
 * 不应在拖拽移动过程中调用。
 */
export const saveSnapshotAtom = atom(
  null,
  (get, set) => {
    const snapshot: Snapshot = {
      nodes: get(nodesAtom),
      edges: get(edgesAtom),
    };
    const stack = get(undoStackAtom);
    const newStack = stack.length >= 50 ? [...stack.slice(1), snapshot] : [...stack, snapshot];
    set(undoStackAtom, newStack);
    set(redoStackAtom, []); // 新操作清空 redo
  }
);

/**
 * 专用于节点拖拽结束时的快照保存（onNodeDragStop 事件）。
 * 整个拖拽过程只产生一个历史点，不会填满撤销栈。
 */
export const saveSnapshotOnDragEndAtom = atom(
  null,
  (get, set) => {
    const snapshot: Snapshot = {
      nodes: get(nodesAtom),
      edges: get(edgesAtom),
    };
    const stack = get(undoStackAtom);
    // 只保留最近 50 个快照
    if (stack.length >= 50) {
      set(undoStackAtom, [...stack.slice(1), snapshot]);
    } else {
      set(undoStackAtom, [...stack, snapshot]);
    }
    // 拖拽结束不清除 redo，允许用户跨拖拽撤销/重做
  }
);

export const undoAtom = atom(
  null,
  (get, set) => {
    const stack = get(undoStackAtom);
    if (stack.length === 0) return;
    const prev = stack[stack.length - 1];
    const current: Snapshot = {
      nodes: get(nodesAtom),
      edges: get(edgesAtom),
    };
    set(nodesAtom, prev.nodes);
    set(edgesAtom, prev.edges);
    set(undoStackAtom, stack.slice(0, -1));
    set(redoStackAtom, [...get(redoStackAtom), current]);
  }
);

export const redoAtom = atom(
  null,
  (get, set) => {
    const stack = get(redoStackAtom);
    if (stack.length === 0) return;
    const next = stack[stack.length - 1];
    const current: Snapshot = {
      nodes: get(nodesAtom),
      edges: get(edgesAtom),
    };
    set(nodesAtom, next.nodes);
    set(edgesAtom, next.edges);
    set(redoStackAtom, stack.slice(0, -1));
    set(undoStackAtom, [...get(undoStackAtom), current]);
  }
);

export const clearWorkflowAtom = atom(
  null,
  (_get, set) => {
    set(nodesAtom, []);
    set(edgesAtom, []);
    set(selectedNodeIdAtom, null);
  }
);

export const loadWorkflowAtom = atom(
  null,
  (_get, set, { nodes, edges, name }: { nodes: Node[]; edges: Edge[]; name?: string }) => {
    set(nodesAtom, nodes);
    set(edgesAtom, edges);
    if (name) set(workflowNameAtom, name);
  }
);
