'use client';

import { useMemo } from 'react';
import { useAtomValue, useSetAtom } from 'jotai';
import {
  imageApiAtom,
  videoApiAtom,
  textApiAtom,
  temperatureAtom,
  maxTokensAtom,
  isLoadedAtom,
  setImageApiAtom,
  setVideoApiAtom,
  setTextApiAtom,
  setTemperatureAtom,
  setMaxTokensAtom,
} from './settings-store-jotai';

export function useSettingsStore() {
  const imageApi = useAtomValue(imageApiAtom);
  const videoApi = useAtomValue(videoApiAtom);
  const textApi = useAtomValue(textApiAtom);
