{"content":"'use client';

import { useEffect, useRef } from 'react';
import { useReactFlow } from '@xyflow/react';
import { useAtom, useAtomValue } from 'jotai';
import {
  selectedNodeIdAtom,
  removeNodeAtom,
  undoAtom,
  redoAtom,
} from '@/stores/workflow-store-jotai';

export function useKeyboardShortcuts() {
  const { zoomIn, zoomOut, fitView } = useReactFlow();
  const selectedNodeId = useAtomValue(selectedNodeIdAtom);
  const [, removeNode] = useAtom(removeNodeAtom);
  const [, undo] = useAtom(undoAtom);
  const [, redo] = useAtom(redoAtom);

  // 使用 useRef 存储 selectedNodeId，避免重复绑定事件监听器
  const selectedNodeIdRef = useRef(selectedNodeId);
  selectedNodeIdRef.current = selectedNodeId;

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const isInputFocused =
        document.activeElement?.tagName === 'INPUT' ||
        document.activeElement?.tagName === 'TEXTAREA' ||
        document.activeElement?.tagName === 'SELECT';

      // Delete/Backspace 删除选中节点
      if ((e.key === 'Delete' || e.key === 'Backspace') && selectedNodeIdRef.current) {
        if (isInputFocused) return;
        e.preventDefault();
        removeNode(selectedNodeIdRef.current);
      }

      // Ctrl/Cmd + Z 撤销
      if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) {
        if (isInputFocused) return;
        e.preventDefault();
        undo();
      }

      // Ctrl/Cmd + Shift + Z 重做
      if ((e.ctrlKey || e.metaKey) && e.key === 'z' && e.shiftKey) {
        if (isInputFocused) return;
        e.preventDefault();
        redo();
      }

      // Ctrl/Cmd + = 放大
      if ((e.ctrlKey || e.metaKey) && e.key === '=') {
        e.preventDefault();
        zoomIn();
      }

      // Ctrl/Cmd + - 缩小
      if ((e.ctrlKey || e.metaKey) && e.key === '-') {
        e.preventDefault();
        zoomOut();
      }

      // Ctrl/Cmd + 0 适应画布
      if ((e.ctrlKey || e.metaKey) && e.key === '0') {
        e.preventDefault();
        fitView();
      }
    };

    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [undo, redo, removeNode, zoomIn, zoomOut, fitView]); // 移除 selectedNodeId
}
