// BDD 场景：节点组件类型安全

describe('node component type safety', () => {
  // BDD: NodeProps 泛型应提供正确类型
  it('should provide correct type with NodeProps generic', () => {
    interface NodeData {
      label: string;
      assetUrl?: string;
    }

    // 模拟 NodeProps 泛型
    interface NodeProps<T> {
      data: T;
      id: string;
    }

    // 正确的类型定义
    const props: NodeProps<NodeData> = {
      id: 'node1',
      data: { label: '图片', assetUrl: 'http://example.com/img.jpg' },
    };

    // 直接访问 data，不需要类型断言
    expect(props.data.label).toBe('图片');
    expect(props.data.assetUrl).toBe('http://example.com/img.jpg');
  });

  // BDD: 不需要 as unknown as NodeData
  it('should not need type assertion', () => {
    interface NodeData {
      label: string;
    }

    const props = {
      id: 'node1',
      data: { label: '测试' } as NodeData,
    };

    // 直接访问，不需要 as unknown as NodeData
    const label = props.data.label;
    expect(label).toBe('测试');
  });
});
