      const url = upstream.assetUrl;
      if (!url) continue;
      const assetType = upstream.assetType || detectAssetTypeFromUrl(url);
      if (assetType === "IMAGE") {
        assets.image = { url, assetId: upstream.node.data?.assetId || "" };
