### `use-upstream-data.ts`（接口增强）
```tsx
import { atom } from 'jotai';
import { atomFamily } from 'jotai/utils';
import { nodesAtom, edgesAtom } from '@/stores/workflow-store-jotai';
import type { NodeData } from '@/types/workflow-v1';
import type { Node, Edge } from '@xyflow/react';

export interface UpstreamNode {
  node: Node<NodeData>;
  edge: Edge;
  assetName: string;
  assetType?: string;
  assetUrl?: string;
}

export const upstreamNodesAtomFamily = atomFamily((nodeId: string) =>
  atom((get): UpstreamNode[] => {
    const nodes = get(nodesAtom);
    const edges = get(edgesAtom);
    const incomingEdges = edges.filter(e => e.target === nodeId);
    return incomingEdges
      .map(edge => {
        const sourceNode = nodes.find(n => n.id === edge.source);
        if (!sourceNode) return null;
        return {
          node: sourceNode as Node<NodeData>,
          edge,
          assetName: sourceNode.data.assetName || '素材',
          assetType: sourceNode.data.assetType,
          assetUrl: sourceNode.data.assetUrl,
        };
      })
      .filter((u): u is UpstreamNode => u !== null);
  })
);

// mentionsAtomFamily, downstreamNodesAtomFamily 同理使用 UpstreamNode 类型
