              : "0 4px 12px rgba(0, 0, 0, 0.3)",
          transition: "all 0.2s cubic-bezier(0.4, 0, 0.2, 1)",
          position: "relative",
        }}
      >
        {children}
      </div>

      <Handle
        type="target"
