```tsx
/* eslint-disable */
"use client";

import React, { memo, useState, useRef, useCallback, useEffect } from "react";
import { getApiBase } from "@/lib/api-base";
import BaseNode from "./base-node";
import type { NodeProps } from "@xyflow/react";
import type { NodeData } from "@/types/workflow-v1";
import { useSettingsStore } from "@/stores/settings-store-compat";
import { useAtom, useAtomValue } from "jotai";
import {
  selectedNodeIdAtom,
  updateNodeDataAtom,
  selectNodeAtom,
  showControlPanelAtom,
} from "@/stores/workflow-store-jotai";
import PreviewModal from "@/components/preview-modal";
import MentionInput from "@/components/mention-input";
import { proxyUrl } from "@/lib/media-proxy";
import { usePollPublicUrl } from "@/hooks/use-poll-public-url";
import { upstreamNodesAtomFamily, mentionsAtomFamily } from "@/hooks/use-upstream-data";

// 已验证的图片模型
const IMAGE_MODELS = [
  "gemini-3-pro-image-preview-official",
  "nano_banana_2",
];

// 各模型支持的清晰度
const MODEL_RESOLUTIONS: Record<string, string[]> = {
  "gemini-3-pro-image-preview-official": ["1K", "2K", "4K"],
  "nano_banana_2": ["0.5K", "1K", "2K", "4K"],
};

const RESOLUTION_LABELS: Record<string, string> = {
  "0.5K": "快速 0.5K",
  "1K": "标准 1K",
  "2K": "高清 2K",
  "4K": "超清 4K",
};

const getSupportedResolutions = (model: string): string[] => {
  return MODEL_RESOLUTIONS[model] || ["1K", "2K", "4K"];
};

const IMAGE_SIZES = [
  { label: "1:1 方形", value: "1:1" },
  { label: "小红书 3:4", value: "3:4" },
  { label: "淘宝服装 3:4", value: "3:4" },
  { label: "抖音 9:16", value: "9:16" },
  { label: "通用 1:1", value: "1:1" },
  { label: "通用 16:9", value: "16:9" },
  { label: "通用 9:16", value: "9:16" },
  { label: "通用 4:3", value: "4:3" },
  { label: "通用 3:2", value: "3:2" },
];

function ImageNode(props: NodeProps<NodeData>) {
  const d = props.data;
  const cfg = d.config as {
    content?: string;
    prompt?: string;
    model?: string;
    size?: string;
    resolution?: string;
    resultUrl?: string;
    taskId?: string;
    assetUrl?: string;
    assetId?: string;
    assetName?: string;
    isLocalAsset?: boolean;
  };

  const { imageApi } = useSettingsStore();
  const [selectedNodeId] = useAtom(selectedNodeIdAtom);
  const [, updateNodeData] = useAtom(updateNodeDataAtom);
  const [, selectNode] = useAtom(selectNodeAtom);
  const [, setShowControlPanel] = useAtom(showControlPanelAtom);
  const upstreamNodes = useAtomValue(upstreamNodesAtomFamily(props.id));
  const mentions = useAtomValue(mentionsAtomFamily(props.id));

  const [prompt, setPrompt] = useState(cfg.content ?? "");
  const [model, setModel] = useState(cfg.model ?? IMAGE_MODELS[0]);
  const [size, setSize] = useState(cfg.size ?? IMAGE_SIZES[0].value);
  const [resolution, setResolution] = useState(
    cfg.resolution ?? getSupportedResolutions(cfg.model ?? IMAGE_MODELS[0])[0]
  );

  useEffect(() => {
    const supported = getSupportedResolutions(model);
    if (!supported.includes(resolution)) {
      setResolution(supported[0]);
    }
  }, [model]);

  const getPreviewHeight = (ratio: string) => {
    const [w, h] = ratio.split(":").map(Number);
    return Math.round(320 * h / w);
  };
  const previewHeight = getPreviewHeight(size);

  const [previewUrl, setPreviewUrl] = useState(d.assetUrl ?? null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [showPreview, setShowPreview] = useState(false);
  const showControls = selectedNodeId === props.id;
  const pollRef = useRef<NodeJS.Timeout | null>(null);

  // 清理定时器
  useEffect(() => {
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  // 监听外部 assetUrl 变化，自动同步预览
  useEffect(() => {
    if (d.assetUrl && d.assetUrl !== previewUrl) {
      setPreviewUrl(d.assetUrl);
      setMode("upload");
    }
  }, [d.assetUrl]);

  const updateResult = useCallback(
    (url: string, assetId: string) => {
      // 仅更新数据，预览由上方的 useEffect 驱动
      updateNodeData(props.id, {
        status: "success",
        assetType: "IMAGE" as const,
        assetUrl: url,
        assetId,
      });
    },
    [props.id, updateNodeData]
  );

  const pollPublicUrl = usePollPublicUrl();

  const handleGenerate = async () => {
    if (!prompt.trim()) {
      setError("请输入提示词");
      return;
    }
    setError(null);
    setLoading(true);
    setProgress(5); // 立即显示进度条
    updateNodeData(props.id, { status: "running", progress: 0 });

    let referenceImageUrls: string[] = [];
    let referenceVideoUrls: string[] = [];
    let imageNames: string[] = [];
    let videoNames: string[] = [];

    for (const upstream of upstreamNodes) {
      if (!upstream) continue;
      const url = upstream.assetUrl;
      if (!url) continue;
      if (upstream.assetType === "IMAGE") {
        referenceImageUrls.push(url);
        imageNames.push(upstream.assetName);
      } else if (upstream.assetType === "VIDEO") {
        referenceVideoUrls.push(url);
        videoNames.push(upstream.assetName);
      }
    }

    let fullPrompt = prompt;
    const refs: string[] = [];
    imageNames.forEach((name, i) => refs.push(`[图片素材${i + 1}: ${name}]`));
    videoNames.forEach((name, i) => refs.push(`[视频素材${i + 1}: ${name}]`));
    if (refs.length > 0) fullPrompt = `${refs.join(" ")}\n${prompt}`;

    try {
      const resp = await fetch(getApiBase() + "/api/generate/image", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: fullPrompt,
          model,
          size,
          resolution,
          reference_image_urls: referenceImageUrls.length > 0 ? referenceImageUrls : undefined,
          reference_video_urls: referenceVideoUrls.length > 0 ? referenceVideoUrls : undefined,
        }),
      });

      if (!resp.ok) {
        const err = await resp.json();
        throw new Error(err.detail || "创建任务失败");
      }

      const data = await resp.json();
      if (data.task_id) {
        if (pollRef.current) clearInterval(pollRef.current);
        pollRef.current = setInterval(async () => {
          try {
            const pollResp = await fetch(
              `${getApiBase()}/api/generate/task/image/${data.task_id}`
            );
            if (!pollResp.ok) return;
            const pollData = await pollResp.json();
            setProgress(pollData.progress || 0);

            if (pollData.status === "completed" && pollData.url) {
              clearInterval(pollRef.current!);
              setProgress(100);
              setTimeout(() => {
                updateResult(pollData.url, pollData.asset_id || "");
                setLoading(false);
              }, 600);
            } else if (pollData.status === "failed") {
              clearInterval(pollRef.current!);
              setError(pollData.error || "生成失败");
              setLoading(false);
              updateNodeData(props.id, { status: "error" });
            }
          } catch {}
        }, 1500);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : "生成失败");
      setLoading(false);
      updateNodeData(props.id, { status: "error" });
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault(); // 仅保留视觉反馈，不上传
  };

  return (
    <BaseNode {...props}>
      <div style={{ position: "relative" }}>
        {/* 素材名称 */}
        <div
          style={{
            position: "absolute",
            top: -20,
            left: 4,
            display: "flex",
            alignItems: "center",
            gap: 4,
            padding: "2px 6px",
            background: "rgba(0, 0, 0, 0.6)",
            borderRadius: 4,
            zIndex: 5,
            pointerEvents: "none",
          }}
        >
          <span style={{ fontSize: 11, color: "rgba(255,255,255,0.9)", fontWeight: 500 }}>
            {d.assetName || "图素材"}
          </span>
        </div>

        {/* 预览框 */}
        <div
          onClick={() => selectNode(props.id)}
          style={{
            width: "100%",
            height: previewHeight,
            cursor: "pointer",
            background: "#1a1a1a",
            transition: "all 0.2s cubic-bezier(0.4, 0, 0.2, 1)",
            position: "relative",
            overflow: "hidden",
          }}
        >
          {previewUrl ? (
            <img
              src={proxyUrl(previewUrl)}
              alt="预览"
              style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
            />
          ) : (
            <div
              onDragOver={(e) => e.preventDefault()}
              onDrop={handleDrop}
              onClick={(e) => { e.stopPropagation(); selectNode(props.id); }}
              style={{
                width: "100%",
                height: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: 12,
                background: "transparent",
              }}
            >
              <svg width="48" height="48" viewBox="0 0 48 48" fill="none">
                <rect x="6" y="10" width="36" height="28" rx="4" stroke="rgba(255,255,255,0.3)" strokeWidth="2" />
                <circle cx="18" cy="22" r="4" stroke="rgba(255,255,255,0.3)" strokeWidth="2" />
                <path d="M6 32L16 24L24 30L32 22L42 32" stroke="rgba(255,255,255,0.3)" strokeWidth="2" />
              </svg>
              <p style={{ fontSize: 13, color: "rgba(255,255,255,0.6)", margin: 0 }}>
                上传素材请通过画布右键或左侧菜单
              </p>
            </div>
          )}

          {/* 进度条（亮白） */}
          {loading && (
            <div
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                right: 0,
                height: 3,
                background: "rgba(255,255,255,0.1)",
              }}
            >
              <div
                style={{
                  width: `${progress}%`,
                  height: "100%",
                  background: "linear-gradient(90deg, #ffffff, #e0e0e0)",
                  transition: "width 0.3s ease",
                }}
              />
            </div>
          )}
        </div>

        {/* 错误提示 */}
        {error && (
          <div style={{ padding: "6px 14px", background: "#0a0a0f" }}>
            <p style={{ fontSize: 11, color: "#ef4444", margin: 0 }}>{error}</p>
          </div>
        )}
      </div>

      {/* 控制面板（生成按钮颜色改为白色） */}
      {showControls && (
        <div
          className="nodrag"
          data-dialog="true"
          onWheel={(e) => e.stopPropagation()}
          onMouseDown={(e) => e.stopPropagation()}
          onMouseEnter={() => document.body.setAttribute("data-hover-dialog", "true")}
          onMouseLeave={() => document.body.removeAttribute("data-hover-dialog")}
          style={{
            position: "absolute",
            top: "100%",
            left: -40,
            width: 520,
            marginTop: 12,
            background: "rgba(28, 28, 30, 0.95)",
            backdropFilter: "saturate(180%) blur(20px)",
            border: "1px solid rgba(255, 255, 255, 0.12)",
            borderRadius: 16,
            padding: 0,
            boxShadow: "0 12px 40px rgba(0,0,0,0.5)",
            zIndex: 100,
            resize: "both",
            overflow: "auto",
          }}
        >
          {/* ... 面板内容不变，只将生成按钮颜色改为白色 ... */}
          <button
            onClick={() => handleGenerate()}
            disabled={loading || !prompt.trim()}
            style={{
              width: 48,
              height: 48,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              background: loading
                ? "rgba(255,255,255,0.08)"
                : "rgba(255,255,255,0.15)",
              border: "1px solid rgba(255,255,255,0.2)",
              borderRadius: 12,
              cursor: loading ? "not-allowed" : "pointer",
              color: loading ? "rgba(255,255,255,0.3)" : "#ffffff",
              flexShrink: 0,
            }}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M12 19V5M5 12l7-7 7 7" />
            </svg>
          </button>
          {/* ... */}
        </div>
      )}

      {showPreview && previewUrl && (
        <PreviewModal
          url={previewUrl}
          type="image"
          onClose={() => setShowPreview(false)}
        />
      )}
    </BaseNode>
  );
}

export default memo(ImageNode);
