{"content":"-- 创建积分扣减的原子操作函数（支持动态配额）
-- 这个函数在数据库层面保证原子性，避免并发问题

CREATE OR REPLACE FUNCTION deduct_credits(
  p_user_id UUID,
  p_month DATE,
  p_amount INTEGER
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_current_used INTEGER;
  v_total INTEGER;
  v_plan TEXT;
  v_new_used INTEGER;
  v_remaining INTEGER;
  v_success BOOLEAN;
  v_message TEXT;
BEGIN
  -- 获取用户订阅计划
  SELECT COALESCE(subscription_plan, 'free') INTO v_plan
  FROM user_profiles
  WHERE id = p_user_id;

  -- 根据计划确定配额
  CASE v_plan
    WHEN 'pro' THEN v_total := 1000;
    WHEN 'business' THEN v_total := 5000;
    ELSE v_total := 100; -- free
  END CASE;

  -- 使用行锁防止并发
  SELECT COALESCE(credits_used, 0) INTO v_current_used
  FROM usage_stats
