{"content":"import { describe, it, expect } from 'vitest';

// BDD 场景：参数透传

describe('parameter passthrough', () => {
  // BDD: 视频比例应正确传递
  it('should pass ratio as aspect_ratio', () => {
    const request = {
      prompt: 'test',
      model: 'seedance-2',
      ratio: '9:16',
    };

    // 后端应映射 ratio -> aspect_ratio
    const body = {
      prompt: request.prompt,
      model: request.model,
      aspect_ratio: request.ratio,
    };

    expect(body.aspect_ratio).toBe('9:16');
  });

  // BDD: 视频模式应正确传递
  it('should pass video_mode', () => {
    const request = {
      prompt: 'test',
      video_mode: 'first_frame',
      first_frame_url: 'https://example.com/frame.jpg',
    };

    expect(request.video_mode).toBe('first_frame');
    expect(request.first_frame_url).toBeTruthy();
  });

  // BDD: 参考素材应正确传递
  it('should pass reference images', () => {
    const request = {
      prompt: 'test',
      reference_images: [
        { url: 'https://example.com/img1.jpg', role: 'style', name: '风格图' },
      ],
    };

    expect(request.reference_images).toBeInstanceOf(Array);
    expect(request.reference_images.length).toBeGreaterThan(0);
    expect(request.reference_images[0].role).toBe('style');
  });

  // BDD: 图片清晰度应为顶层字段
  it('should pass resolution as top-level field', () => {
    const request = {
      prompt: 'test',
      resolution: '2K',
    };

    const body = {
      prompt: request.prompt,
      resolution: request.resolution,
    };

    // 不应包装在 metadata 中
    expect(body.resolution).toBe('2K');
  });
});
